                sb.append((char) b);
            } else {
                // Handle multi-byte UTF-8 characters
                int numBytes = 0;
                if ((b & 0x80) == 0) {
                    numBytes = 1;
                } else if ((b & 0xE0) == 0xC0) {
                    numBytes = 2;
                } else if ((b & 0xF0) == 0xE0) {
