public String format(LoggingEvent event){
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    StringBuilder result = new StringBuilder();
   _formatElement("%d{yyyy-MM-dd HH:mm:ss,SSS}", event.getTimeStamp(), result);
    result.append(" ");
    _formatElement("%c", event.getLoggerName(), result);
    result.append(" ");
    _formatElement("%p", event.getPriority().toString(), result);
    result.append(" ");
    _formatElement("%m%n", event.getMessage(), result);
    return result.toString();
}

private void _formatElement(String conversionPattern, Object value, StringBuilder result) {
    if (conversionPattern.startsWith("%d")) {
        if (value instanceof Long) {
            long time = (Long) value;
            result.append(new SimpleDateFormat("yyyy-MM-dd HH:mm:ss,SSS").format(new Date(time)));
        }
    } else if (conversionPattern.startsWith("%c")) {
        if (value instanceof String) {
            result.append(value);
        }
    } else if (conversionPattern.startsWith("%p")) {
        if (value instanceof Level) {
            result.append(((Level) value).toString());
        }
    } else if (conversionPattern.startsWith("%m%n")) {
        if (value instanceof String) {
            result.append(value).append(System.lineSeparator());
        }
    }
}
