@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }

    // Define the sets for the bipartite graph
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    // Populate the sets with unique vertices
    for (int i = 0; i < resultMap.size(); i++) {
        V vertex1 = resultMap.get("vertex" + i);
        V vertex2 = resultMap.get("vertex" + (i + resultMap.size() / 2));
        set1.add(vertex1);
        set2.add(vertex2);
    }

    // Ensure the sets do not overlap
    if (!set1.isDisjoint(set2)) {
        throw new IllegalArgumentException("Vertices must be divided into disjoint sets");
    }

    // Add edges between all vertices in set1 and set2
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            target.addEdge(vertex1, vertex2);
        }
    }

    // Optionally, add vertices to the target graph
    target.addVertices(set1);
    target.addVertices(set2);
}
