int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    try {
        if (message == null) {
            throw new IOException("Message cannot be null");
        }

        if (out == null) {
            throw new IOException("OutputStream cannot be null");
        }

        if (schema == null) {
            throw new IOException("Schema cannot be null");
        }

        if (buffer == null) {
            throw new IOException("LinkedBuffer cannot be null");
        }

        byte[] data = schema.toByteArray(message);
        int size = data.length;

        if (size > MAX_VARINT_SIZE) {
            throw new IOException("Message is too large to be serialized as a varint size");
        }

        writeVarint32(out, size);
        out.write(data);
        buffer.clear();
        return size;
    } catch (IOException e) {
        throw e;
    }
}

private static final int MAX_VARINT_SIZE = 5;

private static void writeVarint32(OutputStream out, int value) throws IOException {
    while (true) {
        if ((value & 0xFFFFFF80) == 0) {
            out.write(value);
            return;
        } else {
            out.write((byte) (value & 0x7F | 0x80));
            value >>>= 7;
        }
    }
}
