public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
  // Serialize the message to a ByteBuffer
  ByteBuffer byteBuffer = schema.toByteArray(message);

  // Write the length prefix to the output stream
  int size = byteBuffer.remaining();
  out.write(size);

  // Write the serialized message to the output stream
  byteBuffer.flip();
  while (byteBuffer.hasRemaining()) {
    out.write(byteBuffer.get());
  }

  // Return the size of the message
  return size;
}

