public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    try {
        int length = schema.getByteBufferLength(message);
        if (length < 0) {
            throw new IllegalArgumentException("Invalid message length");
        }

        out.write(length >>> 24);
        out.write((length >>> 16) & 0xFF);
        out.write((length >>> 8) & 0xFF);
        out.write(length & 0xFF);

        schema.writeTo(buffer, message);
        out.write(buffer.array(), buffer.offset(), buffer.size());
        return length + buffer.size();
    } catch (IOException e) {
        throw new RuntimeException("Failed to write message to output stream", e);
    }
}
