    int serializedSize = schema.getSerializedSize(message);
    buffer.reset(serializedSize + 4);
    if (buffer.writeVarint32(serializedSize) < 0) {
        throw new IOException("Failed to write varint32");
    }
    buffer.append(schema, message, buffer);
    if (buffer.writeTo(out) < 0) {
        throw new IOException("Failed to write to output stream");
