public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    if (size > LinkedBuffer.MAX_SIZE) {
        throw new IllegalArgumentException("Message exceeds maximum size");
    }

    // Write the size of the message first
    byte[] sizeBytes = CodedOutputStream.encodeZigZag32(size);
    out.write(sizeBytes);
    buffer.readFrom(new CodedInputStream(sizeBytes));

    // Serialize the message
    int written = schema.write(message, buffer);
    buffer.flushTo(out);

    return size;
}
