    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();
    Class<?>[] resolvedArguments = new Class<?>[typeParameters.length];

    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    buildTypeVariableMap(targetType, typeVariableMap);

    for (int i = 0; i < typeParameters.length; i++) {
        TypeVariable<?> typeVariable = typeParameters[i];
        Type resolvedType = typeVariableMap.get(typeVariable);
        if (resolvedType instanceof Class<?>) {
            resolvedArguments[i] = (Class<?>) resolvedType;
        } else if (resolvedType instanceof WildcardType) {
            WildcardType wildcardType = (WildcardType) resolvedType;
            Type[] upperBounds = wildcardType.getUpperBounds();
            if (upperBounds.length > 0) {
