private Class<?> resolveRawType(Type type, Class<?> targetType) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        return resolveRawType(parameterizedType.getRawType(), targetType);
    } else if (type instanceof TypeVariable<?>) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        if (targetType.getParameterizedType() instanceof ParameterizedType) {
            ParameterizedType parameterizedTargetType = (ParameterizedType) targetType.getParameterizedType();
            Type[] actualTypeArguments = parameterizedTargetType.getActualTypeArguments();
            TypeVariable<?>[] typeVariables = targetType.getTypeParameters();
            for (int i = 0; i < typeVariables.length; i++) {
                if (typeVariables[i].equals(typeVariable)) {
                    return resolveRawType(actualTypeArguments[i], targetType);
                }
            }
        }
    } else if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (upperBounds.length > 0) {
            return resolveRawType(upperBounds[0], targetType);
        }
    }
    return Object.class;
}

