static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 100000000);
    int month = (int) (timeBucket / 1000000 % 100);
    int day = (int) (timeBucket / 10000 % 100);

    // Determine the new day based on the dayStep
    int newDay = day;
    if (dayStep == 11) {
        newDay = 1;
    } else if (dayStep == 12) {
        newDay = 2;
    } else if (dayStep == 13) {
        newDay = 3;
    } else {
        throw new IllegalArgumentException("Invalid dayStep value");
    }

    // Reconstruct the time bucket with the new day
    return year * 100000000 + month * 1000000 + newDay * 10000;
