public static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) (timeBucket % 10000 / 100);
    int day = (int) (timeBucket % 100);

    // Adjust the day based on dayStep
    dayStep = Math.abs(dayStep);
    while (day > 0 && day + dayStep > 31) {
        day -= 30; // Assuming a month has at least 30 days for simplicity
        month++;
    }
    day += dayStep;

    // Handle month overflow
    if (month > 12) {
        year++;
        month -= 12;
    }

    // Combine year, month, and adjusted day to form the new time bucket
    return year * 10000 + month * 100 + day;
}
