public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        byte[] utf8Bytes = str.toString().getBytes("UTF-8");
        int length = utf8Bytes.length;
        if (length > lb.capacity()) {
            throw new BufferOverflowException("Buffer overflow: string too long");
        }
        System.arraycopy(utf8Bytes, 0, lb.getData(), lb.getOffset(), length);
        lb.move(length);
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }

    return lb;
}
