public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    boolean escape = false;

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);

        if (escape) {
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new IllegalArgumentException("invalid escape character: " + c);
            }
            escape = false;
        } else if (c == '\\') {
            escape = true;
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

