    boolean inEscape = false;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (c == '\\') {
            if (inEscape) {
                sb.append(c);
                inEscape = false;
            } else {
                inEscape = true;
            }
        } else if (inEscape) {
            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
