import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class UriMatcher {

    private final Pattern matchPattern;
    private final Pattern groupPattern;

    public UriMatcher(String uriTemplate) {
        this.matchPattern = Pattern.compile("^" + uriTemplate + "$");
        this.groupPattern = Pattern.compile("(.*?)%");
    }

    /**
     * Match a URI against the pattern.
     * @param uri the uri to match against the template.
     * @return the match result, otherwise null if no match occurs.
     */
    public final MatchResult match(CharSequence uri) {
        if (uri == null) {
            return null;
        }
        Matcher matcher = matchPattern.matcher(uri.toString());
        if (!matcher.matches()) {
            return null;
        }
        GroupResult[] groups = new GroupResult[groupPattern.splitAsStream(uriTemplate).count()];
        int i = 0;
        for (String group : groupPattern.splitAsStream(uriTemplate)) {
            groups[i++] = new GroupResult(group, matcher.group(i));
        }
        return new MatchResult(groups);
    }

    public static class MatchResult {
        private final GroupResult[] groups;

        public MatchResult(GroupResult[] groups) {
            this.groups = groups;
        }

        public GroupResult[] getGroups() {
            return groups;
        }

        @Override
        public String toString() {
            StringBuilder result = new StringBuilder();
            for (GroupResult group : groups) {
                result.append(group.getName()).append("=").append(group.getValue()).append(", ");
            }
            return result.toString();
        }
    }

    public static class GroupResult {
        private final String name;
        private final String value;

        public GroupResult(String name, String value) {
            this.name = name;
            this.value = value;
        }

        public String getName() {
            return name;
        }

        public String getValue() {
            return value;
        }

        @Override
        public String toString() {
            return name + "=" + value;
        }
    }
}
