protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Initialize a list to store the vertices of the path
    List<V> pathVertices = new ArrayList<>();

    // Check if the tour is empty
    if (tour.isEmpty()) {
        return graph.createPath(pathVertices);
    }

    // Convert the set of edges to a list for easier processing
    List<E> edgeList = new ArrayList<>(tour);

    // Start from the first edge and traverse the tour
    GraphEdge<V,E> firstEdge = (GraphEdge<V,E>) edgeList.get(0);
    V startVertex = firstEdge.getEndpoint1();
    V currentVertex = startVertex;

    // Add the start vertex to the path
    pathVertices.add(startVertex);

    // Traverse the tour and build the path
    for (E edge : edgeList) {
        if (edge.getEndpoint1().equals(currentVertex)) {
            pathVertices.add(edge.getEndpoint2());
            currentVertex = edge.getEndpoint2();
        } else if (edge.getEndpoint2().equals(currentVertex)) {
            pathVertices.add(edge.getEndpoint1());
            currentVertex = edge.getEndpoint1();
        } else {
            // If the graph is not connected or the tour is invalid, return null
            return null;
        }
    }

    // Create and return the graph path
    return graph.createPath(pathVertices);
}
