    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Inputs cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createEmptyPath();
    }

    V current = null;
    for (E edge : edges) {
        if (current == null) {
            current = graph.getSource(edge);
        } else {
            if (!graph.getSource(edge).equals(current)) {
                throw new IllegalArgumentException("Edges do not form a valid tour");
            }
            current = graph.getTarget(edge);
        }
    }

    return graph.createPath(edges);
}
