public boolean isCompatible(DataTable dataset) {
    if (dataset == null) {
        throw new IllegalArgumentException("Dataset cannot be null");
    }
    // Check if the number of columns and rows match
    if (this.getColumns().size() != dataset.getColumns().size() ||
        this.getRows().size() != dataset.getRows().size()) {
        return false;
    }
    // Check if the data types match for each column
    for (int i = 0; i < this.getColumns().size(); i++) {
        if (!this.getColumns().get(i).getClass().equals(dataset.getColumns().get(i).getClass())) {
            return false;
        }
    }
    // Check if the data matches for each cell
    for (int i = 0; i < this.getRows().size(); i++) {
        for (int j = 0; j < this.getColumns().size(); j++) {
            if (!this.getCells(i, j).equals(dataset.getCells(i, j))) {
                return false;
            }
        }
    }
    return true;
}
