        return;
    }

    List<ListNodeImpl<E>> nodes = new ArrayList<>();
    ListNodeImpl<E> currentNode = list.getHead();

    while (currentNode != null) {
        nodes.add(currentNode);
        currentNode = currentNode.getNext();
    }

    list.clear();

    for (ListNodeImpl<E> node : nodes) {
        addListNode(node);
