    try {
        Class<?> clazz = getClass();
        while (clazz != null) {
            try {
                clazz.getDeclaredField(key.toString());
                return true;
            } catch (NoSuchFieldException e) {
                clazz = clazz.getSuperclass();
            }
        }
        return false;
    } catch (SecurityException e) {
