List<Pair<List<Pair<Integer,Integer>>,E>> function(UndirectedGraph<Integer,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.getEdges()) {
        E e = edge.getElement();
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

        for (int u : graph.getAdjacencyList().get(edge.getSource())) {
            if (u != edge.getTarget()) {
                Set<Integer> separator = new HashSet<>(graph.getAdjacencyList().get(u));
                separator.retainAll(graph.getAdjacencyList().get(edge.getTarget()));
                localSeparatorList.add(new Pair<>(separator, e));
            }
        }

        globalSeparatorList.addAll(localSeparatorList);
    }

    return globalSeparatorList;
}
