void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null || row < 0 || row >= table.getRowCount()) {
        return;
    }

    // Select the row in the JTable
    table.setRowSelectionInterval(row, row);

    // Get the vertical scroll bar of the JScrollPane
    JScrollBar scrollBar = pane.getVerticalScrollBar();

    // Calculate the rectangle of the selected row
    Rectangle rowBounds = table.getCellRect(row, 0, true);

    // Scroll the JScrollPane to the selected row
    scrollBar.setValue(rowBounds.y - scrollBar.getHeight() / 2);

    // Repaint the component after a delay to ensure the table is properly painted
    SwingUtilities.invokeLater(() -> {
        table.repaint();
    });
}

