public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    try {
        // Normalize the paths
        File basePath = new File(path).getCanonicalFile();
        File relativePathFile = new File(relativePath).getCanonicalFile();

        // If the relative path is absolute, just return it
        if (relativePathFile.isAbsolute()) {
            return relativePathFile.getPath();
        }

        // Create a list of parent directories for the base path
        List<String> basePathParts = new ArrayList<>(Arrays.asList(basePath.getParentFile().getCanonicalPath().split("/")));
        basePathParts.remove(basePath.getName());

        // Create a list of directories in the relative path
        List<String> relativePathParts = new ArrayList<>(Arrays.asList(relativePathFile.getCanonicalPath().split("/")));

        // Remove redundant ".." entries
        Iterator<String> it = relativePathParts.iterator();
        while (it.hasNext()) {
            String part = it.next();
            if ("..".equals(part)) {
                if (!basePathParts.isEmpty()) {
                    basePathParts.remove(basePathParts.size() - 1);
                } else {
                    // If we encounter a ".." before we have any parent directories, it means the relative path is invalid
                    throw new IllegalArgumentException("Invalid relative path: " + relativePath);
                }
                it.remove();
            }
        }

        // Combine the paths
        StringBuilder result = new StringBuilder();
        for (String part : basePathParts) {
            result.append(result.length() > 0 ? "/" : "");
            result.append(part);
        }
        for (String part : relativePathParts) {
            result.append(result.length() > 0 ? "/" : "");
            result.append(part);
        }
        return result.toString();
    } catch (IOException e) {
        throw new RuntimeException("Error processing paths", e);
    }
}
