public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Split the path into parts
    String[] pathParts = path.split("/");
    // Split the relativePath into parts
    String[] relativeParts = relativePath.split("/");

    int appendOffset = 0;
    // Traverse both arrays and compare parts until they differ
    for (; appendOffset < pathParts.length && appendOffset < relativeParts.length; ++appendOffset) {
        if (!pathParts[appendOffset].equals(relativeParts[appendOffset])) {
            break;
        }
    }

    // Build the new path by appending the remaining parts from both path and relativePath
    StringBuilder newPath = new StringBuilder();
    for (int i = appendOffset; i < pathParts.length; ++i) {
        newPath.append("../");
    }
    for (int i = appendOffset; i < relativeParts.length; ++i) {
        newPath.append(relativeParts[i]);
        if (i < relativeParts.length - 1) {
            newPath.append("/");
        }
    }

    return newPath.toString();
}
