public int readTag() throws IOException {
    int firstByte = readRawVarint32();
    if (firstByte == 0) {
        return 0;
    }
    int tag = firstByte >>> 3;
    return tag;
}

private int readRawVarint32() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = read();
        if (b == -1) {
            return 0; // EOF
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Varint is too long");
}
