    if (fieldNumber == 0) {
        throw new InvalidProtocolBufferException("Protocol message contained an invalid tag (0).");
    }
    int wireType = b & 0x07;
    if (wireType == 0) {
        skipRawVarint();
    } else if (wireType == 1) {
        readRawFixed64();
    } else if (wireType == 2) {
        skipRawVarint(); // Length prefix
        readRawBytes(readRawVarint());
    } else if (wireType == 5) {
        readRawFixed32();
    } else {
        throw new InvalidProtocolBufferException("Protocol message had invalid wire type (" + wireType + ").");
    }
    return fieldNumber;
}
